-- STAGING ONLY 481: exact Stock links one canonical vehicle; every current Navision change refreshes its safe descriptive projection.
BEGIN;SET LOCAL statement_timeout='180s';SELECT pg_advisory_xact_lock(hashtextextended('pdc-staging-481-navision-linked-vehicle-refresh',0));
DO $guard$ BEGIN IF current_user<>'postgres' OR session_user<>'postgres' OR (SELECT count(*) FROM public.pdc_staging_environment_sentinel WHERE singleton AND project_ref='cdsmnqxtyyoeoznmbidd')<>1 OR to_regclass('public.pdc_production_environment_sentinel') IS NOT NULL OR NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20260827030000' AND name='480_bind_paused_complete_operation_runtime') OR EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version~'^[0-9]{14}$' AND version>'20260827030000') OR encode(extensions.digest(convert_to(pg_get_functiondef('public.reconcile_navision_operational_record(uuid,uuid,text)'::regprocedure),'UTF8'),'sha256'),'hex')<>'b49ccdfa270eb7a50d2ec059b41b155c82361b5b270e045bb7a11135496efae5' OR encode(extensions.digest(convert_to(pg_get_functiondef('public.get_pdc_email_vehicle_location_snapshot()'::regprocedure),'UTF8'),'sha256'),'hex')<>'a117844b48a04fd674efd8c2e9938b646936fdb5e134a0281e14645385a764c1' OR (SELECT count(*) FROM public.vehicles WHERE stock_number_normalized='13000776' AND deleted_at IS NULL)<>1 OR NOT EXISTS(SELECT 1 FROM public.navision_backend_records b JOIN public.vehicles v ON v.id=b.canonical_vehicle_id WHERE b.id='2da6b82c-734e-4cce-94b2-205d5a727b0b'::uuid AND v.id='99518513-5293-5619-a06e-9b4323754838'::uuid AND b.normalized_data->>'stock'='13000776') THEN RAISE EXCEPTION 'PDC_481_TARGET_HEAD_FUNCTION_OR_IDENTITY_MISMATCH' USING errcode='55000';END IF;END $guard$;
CREATE TABLE public.pdc_owner_navision_link_rules_481(rule_key text PRIMARY KEY CHECK(rule_key='current-navision-updates-linked-canonical-vehicle'),rule_text text NOT NULL CHECK(rule_text='Exact Stock links one canonical operational vehicle. Current Navision changes refresh that linked vehicle descriptive data; operational lifecycle latches, Job Card evidence and explicit manual salesperson overrides remain authoritative.'),created_by_email text NOT NULL CHECK(created_by_email='craig.watson@broometoyota.com.au'),created_at timestamptz NOT NULL DEFAULT clock_timestamp());ALTER TABLE public.pdc_owner_navision_link_rules_481 ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.pdc_owner_navision_link_rules_481 FROM public,anon,authenticated,service_role;INSERT INTO public.pdc_owner_navision_link_rules_481(rule_key,rule_text,created_by_email) VALUES('current-navision-updates-linked-canonical-vehicle','Exact Stock links one canonical operational vehicle. Current Navision changes refresh that linked vehicle descriptive data; operational lifecycle latches, Job Card evidence and explicit manual salesperson overrides remain authoritative.','craig.watson@broometoyota.com.au');
CREATE FUNCTION public.pdc_refresh_linked_vehicle_from_navision_481(p_backend_record_id uuid,p_actor_id uuid,p_actor_email text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,extensions AS $fn$
DECLARE b public.navision_backend_records%rowtype;v public.vehicles%rowtype;before_row jsonb;after_row jsonb;stock text;effective_vin text;customer text;description text;colour text;sales_raw text;sales_code text;sales_id uuid;sales_ref text;changed boolean:=false;BEGIN
 IF NOT public.pdc_monitor_staging_guard() OR p_backend_record_id IS NULL THEN RETURN public.navision_backend_response(false,'wrong_environment_or_invalid_input');END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('navision-linked-refresh:'||p_backend_record_id::text,0));SELECT * INTO b FROM public.navision_backend_records WHERE id=p_backend_record_id FOR UPDATE;
 IF NOT FOUND OR NOT b.is_current OR b.record_status<>'current' OR b.canonical_vehicle_id IS NULL THEN RETURN public.navision_backend_response(true,'no_current_canonical_link',jsonb_build_object('changed',false));END IF;
 stock:=nullif(public.normalize_vehicle_stock_number(b.normalized_data->>'batch'),'');SELECT * INTO v FROM public.vehicles WHERE id=b.canonical_vehicle_id FOR UPDATE;
 IF NOT FOUND OR v.deleted_at IS NOT NULL OR stock IS NULL OR v.stock_number_normalized IS DISTINCT FROM stock THEN RETURN public.navision_backend_response(false,'canonical_link_or_stock_mismatch');END IF;
 IF EXISTS(SELECT 1 FROM public.vehicles x WHERE x.id<>v.id AND x.deleted_at IS NULL AND x.stock_number_normalized=stock) THEN RETURN public.navision_backend_response(false,'duplicate_operational_stock_conflict');END IF;
 effective_vin:=public.pdc_navision_effective_vin_471(b.normalized_data);IF effective_vin IS NULL AND public.is_valid_vehicle_vin(v.vin) AND right(public.normalize_vehicle_vin(v.vin),length(public.normalize_vehicle_vin(b.normalized_data->>'vin')))=public.normalize_vehicle_vin(b.normalized_data->>'vin') THEN effective_vin:=v.vin_normalized;END IF;
 customer:=coalesce(nullif(btrim(b.normalized_data->>'client'),''),nullif(btrim(b.normalized_data->>'customerSurname'),''),nullif(btrim(b.normalized_data->>'toyotaCustomer'),''));description:=coalesce(nullif(btrim(b.normalized_data->>'modelDescription'),''),nullif(btrim(b.normalized_data->>'toyotaVehicle'),''),nullif(btrim(b.normalized_data->>'vehicle'),''));colour:=coalesce(nullif(btrim(b.normalized_data->>'colourDescription'),''),nullif(btrim(b.normalized_data->>'colour'),''));sales_raw:=coalesce(public.navision_original_column_value(b.normalized_data,'Salesperson'),nullif(btrim(b.normalized_data->>'salesperson'),''),nullif(btrim(b.normalized_data->>'consultant'),''),nullif(btrim(b.normalized_data->>'owner'),''));sales_code:=upper(split_part(coalesce(sales_raw,''),' ',1));SELECT id,code INTO sales_id,sales_ref FROM public.salespeople WHERE active AND upper(code)=sales_code ORDER BY sort_order,id LIMIT 1;
 before_row:=to_jsonb(v);UPDATE public.vehicles SET stock_number=coalesce(b.normalized_data->>'batch',stock_number),vin=coalesce(effective_vin,vin),toyota_order_number=coalesce(nullif(btrim(b.normalized_data->>'order'),''),toyota_order_number),job_card_number=coalesce(job_card_number,nullif(btrim(b.normalized_data->>'jobCardNumber'),'')),customer_name=coalesce(customer,customer_name),vehicle_description=coalesce(description,vehicle_description),model=coalesce(description,model),registration=coalesce(nullif(upper(btrim(b.normalized_data->>'registration')),''),registration),salesperson_id=CASE WHEN salesperson_manual_override THEN salesperson_id ELSE coalesce(sales_id,salesperson_id) END,salesperson_reference=CASE WHEN salesperson_manual_override THEN salesperson_reference ELSE coalesce(sales_ref,nullif(sales_raw,''),salesperson_reference) END,source_system='microsoft_navision',source_batch_id=b.dealer_code,source_record_id=b.id::text,source_payload=coalesce(source_payload,'{}'::jsonb)||jsonb_build_object('authority','navision-linked-refresh-481','navision_record_id',b.id,'navision_version',b.version,'navision_updated_at',b.updated_at,'navision_status',b.normalized_data->>'toyotaStatus','navision_colour',colour,'colour',colour,'navision_salesperson',sales_raw,'navision_model',description,'navision_customer',customer,'navision_source_data',b.normalized_data-'navisionRawEvidence'),version=version+1,updated_by=p_actor_id,updated_at=clock_timestamp() WHERE id=v.id AND (stock_number,vin,toyota_order_number,job_card_number,customer_name,vehicle_description,model,registration,salesperson_id,salesperson_reference,source_system,source_batch_id,source_record_id,source_payload) IS DISTINCT FROM (coalesce(b.normalized_data->>'batch',stock_number),coalesce(effective_vin,vin),coalesce(nullif(btrim(b.normalized_data->>'order'),''),toyota_order_number),coalesce(job_card_number,nullif(btrim(b.normalized_data->>'jobCardNumber'),'')),coalesce(customer,customer_name),coalesce(description,vehicle_description),coalesce(description,model),coalesce(nullif(upper(btrim(b.normalized_data->>'registration')),''),registration),CASE WHEN salesperson_manual_override THEN salesperson_id ELSE coalesce(sales_id,salesperson_id) END,CASE WHEN salesperson_manual_override THEN salesperson_reference ELSE coalesce(sales_ref,nullif(sales_raw,''),salesperson_reference) END,'microsoft_navision',b.dealer_code,b.id::text,coalesce(source_payload,'{}'::jsonb)||jsonb_build_object('authority','navision-linked-refresh-481','navision_record_id',b.id,'navision_version',b.version,'navision_updated_at',b.updated_at,'navision_status',b.normalized_data->>'toyotaStatus','navision_colour',colour,'colour',colour,'navision_salesperson',sales_raw,'navision_model',description,'navision_customer',customer,'navision_source_data',b.normalized_data-'navisionRawEvidence')) RETURNING * INTO v;
 changed:=FOUND;IF changed THEN after_row:=to_jsonb(v);INSERT INTO public.audit_events(action,table_name,row_id,vehicle_id,actor_id,actor_email,before_data,after_data,metadata) VALUES('update','vehicles',v.id,v.id,p_actor_id,p_actor_email,before_row,after_row,jsonb_build_object('source','navision-linked-refresh-481','backend_record_id',b.id,'backend_version',b.version,'stock_number',stock,'manual_salesperson_override_preserved',v.salesperson_manual_override,'lifecycle_mutated',false,'job_card_overwritten',false));UPDATE public.pdc_email_vehicle_revision SET revision=revision+1,updated_at=clock_timestamp() WHERE singleton;END IF;
 RETURN public.navision_backend_response(true,CASE WHEN changed THEN 'linked_vehicle_refreshed' ELSE 'linked_vehicle_current' END,jsonb_build_object('vehicle_id',b.canonical_vehicle_id,'backend_record_id',b.id,'backend_version',b.version,'changed',changed,'manual_salesperson_override_preserved',v.salesperson_manual_override));END $fn$;REVOKE ALL ON FUNCTION public.pdc_refresh_linked_vehicle_from_navision_481(uuid,uuid,text) FROM public,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.reconcile_navision_operational_record(p_backend_record_id uuid,p_actor_id uuid DEFAULT NULL::uuid,p_actor_email text DEFAULT NULL::text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,extensions AS $wrapper$ DECLARE v_record public.navision_backend_records%rowtype;v_stock text;v_vin text;v_deleted uuid[];base jsonb;refresh jsonb;BEGIN IF NOT public.pdc_monitor_staging_guard() THEN RETURN public.navision_backend_response(false,'wrong_environment');END IF;IF p_backend_record_id IS NULL THEN RETURN public.navision_backend_response(false,'invalid_input');END IF;PERFORM pg_advisory_xact_lock(hashtextextended('navision-backend-store',0));PERFORM pg_advisory_xact_lock(hashtextextended('navision-operational-record:'||p_backend_record_id::text,0));SELECT * INTO v_record FROM public.navision_backend_records WHERE id=p_backend_record_id FOR UPDATE;IF NOT FOUND OR NOT v_record.is_current OR v_record.record_status<>'current' THEN RETURN public.reconcile_navision_operational_record_pre171(p_backend_record_id,p_actor_id,p_actor_email);END IF;v_stock:=nullif(public.normalize_vehicle_stock_number(v_record.normalized_data->>'batch'),'');v_vin:=public.pdc_navision_effective_vin_471(v_record.normalized_data);SELECT coalesce(array_agg(v.id ORDER BY v.id),'{}'::uuid[]) INTO v_deleted FROM public.vehicles v WHERE v.deleted_at IS NOT NULL AND (v.id=v_record.canonical_vehicle_id OR (v_stock IS NOT NULL AND v.stock_number_normalized=v_stock) OR (v_vin IS NOT NULL AND v.vin_normalized=v_vin));IF cardinality(v_deleted)>0 THEN RETURN public.navision_backend_response(true,'historical_vehicle_retained',jsonb_build_object('backend_record_id',p_backend_record_id,'historical_vehicle_count',cardinality(v_deleted),'operational_change',false));END IF;base:=public.reconcile_navision_operational_record_pre171(p_backend_record_id,p_actor_id,p_actor_email);IF coalesce((base->>'ok')::boolean,false) THEN refresh:=public.pdc_refresh_linked_vehicle_from_navision_481(p_backend_record_id,p_actor_id,p_actor_email);IF NOT coalesce((refresh->>'ok')::boolean,false) THEN RETURN refresh;END IF;RETURN jsonb_set(base,'{data,navision_link_refresh}',coalesce(refresh,'{}'::jsonb),true);END IF;RETURN base;END $wrapper$;
CREATE OR REPLACE FUNCTION public.get_pdc_email_vehicle_location_snapshot() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $snap$ DECLARE r jsonb;rows jsonb;BEGIN r:=public.get_pdc_email_vehicle_location_snapshot_pre_429();IF NOT coalesce((r->>'ok')::boolean,false) THEN RETURN r;END IF;SELECT coalesce(jsonb_agg(x||jsonb_build_object('rft_transport_outbox',coalesce(x->'rft_transport_outbox','{}'::jsonb)||coalesce((SELECT jsonb_build_object('intercept_receipt_id',i.receipt_id,'intercepted_at',i.created_at,'intercept_outcome',i.outcome) FROM public.pdc_rft_transport_email_intercept_receipts_429 i WHERE i.vehicle_id=(x->>'id')::uuid ORDER BY i.created_at DESC LIMIT 1),'{}'::jsonb),'navision_colour',coalesce((SELECT coalesce(nullif(btrim(b.normalized_data->>'colourDescription'),''),nullif(btrim(b.normalized_data->>'colour'),'')) FROM public.navision_backend_records b WHERE b.canonical_vehicle_id=(x->>'id')::uuid AND b.is_current AND b.record_status='current' ORDER BY b.updated_at DESC,b.id LIMIT 1),''),'navision_salesperson_raw',coalesce((SELECT coalesce(public.navision_original_column_value(b.normalized_data,'Salesperson'),b.normalized_data->>'salesperson',b.normalized_data->>'consultant',b.normalized_data->>'owner') FROM public.navision_backend_records b WHERE b.canonical_vehicle_id=(x->>'id')::uuid AND b.is_current AND b.record_status='current' ORDER BY b.updated_at DESC,b.id LIMIT 1),'') ) ORDER BY coalesce(x->>'stock_number',x->>'vin',x->>'id')),'[]'::jsonb) INTO rows FROM jsonb_array_elements(coalesce(r#>'{data,vehicles}','[]'::jsonb)) x;RETURN jsonb_set(r,'{data,vehicles}',rows,true);END $snap$;
SELECT public.pdc_refresh_linked_vehicle_from_navision_481('2da6b82c-734e-4cce-94b2-205d5a727b0b'::uuid,'8a83b715-8d79-4b0e-95b2-02b55da6e8d7'::uuid,'craig.watson@broometoyota.com.au');
DO $post$ BEGIN IF (SELECT count(*) FROM public.vehicles WHERE stock_number_normalized='13000776' AND deleted_at IS NULL)<>1 OR NOT EXISTS(SELECT 1 FROM public.vehicles v JOIN public.navision_backend_records b ON b.canonical_vehicle_id=v.id WHERE v.id='99518513-5293-5619-a06e-9b4323754838'::uuid AND b.id='2da6b82c-734e-4cce-94b2-205d5a727b0b'::uuid AND v.source_record_id=b.id::text AND v.source_system='microsoft_navision' AND v.source_payload->>'navision_colour'='Glacier White' AND v.source_payload->>'navision_salesperson'='BH 19960824' AND v.salesperson_manual_override AND v.salesperson_reference='CW') OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.navision_backend_records'::regclass AND tgname='navision_record_operational_reconcile' AND tgenabled='O') OR pg_get_functiondef('public.reconcile_navision_operational_record(uuid,uuid,text)'::regprocedure) NOT LIKE '%pdc_refresh_linked_vehicle_from_navision_481%' THEN RAISE EXCEPTION 'PDC_481_POSTCONDITION_FAILED' USING errcode='55000';END IF;END $post$;
INSERT INTO supabase_migrations.schema_migrations(version,name,statements) VALUES('20260827031000','481_navision_linked_vehicle_refresh',ARRAY['Persist Craig rule: exact Stock links one canonical operational vehicle and current Navision changes refresh it','Refresh safe descriptive Navision fields on every activated/linked record update while preserving lifecycle latches, Job Card evidence and manual salesperson overrides','Expose current Navision colour and source salesperson in the authoritative vehicle snapshot','Correct Stock 13000776 without creating a second operational vehicle; Production untouched']);NOTIFY pgrst,'reload schema';COMMIT;
